from pathlib import Path

path = Path("tools/research_dispatch.py")
text = path.read_text(encoding="utf-8")

anchor = '''def _overlay_result_state(\n    task: dict[str, Any],\n    state: dict[str, Any],\n    root: Path,\n    result_state: dict[str, Any] | None,\n) -> dict[str, Any]:\n'''

helper = '''def _block_unreviewed_registered_done(\n    task: dict[str, Any],\n    state: dict[str, Any],\n    authenticated: list[dict[str, Any]],\n    registered_rejected: list[dict[str, Any]],\n    result_state: dict[str, Any] | None,\n) -> dict[str, Any]:\n    \"\"\"Fail closed when an authenticated DONE lacks terminal result authority.\n\n    The rejected DONE is not promoted to completion.  It only prevents the same\n    task from falling back to fresh dispatch while its attempted terminal closure\n    is unresolved.  A trusted Result/Driver lifecycle overlay, an active lease,\n    or an active cohort remains authoritative and is never replaced by this guard.\n    \"\"\"\n    if result_state is not None or state.get(\"dispatch_state\") != \"NEEDS_DISPATCH\":\n        return state\n    reason_text = \"registered DONE requires a frozen result with terminal Driver review\"\n    for rejected in registered_rejected:\n        if rejected.get(\"reason\") != reason_text:\n            continue\n        index = rejected.get(\"index\")\n        if type(index) is not int or index < 0 or index >= len(authenticated):\n            continue\n        event = authenticated[index]\n        if event.get(\"task_id\") != task.get(\"task_id\") or event.get(\"event\") != \"DONE\":\n            continue\n        meta = event.get(GITHUB_META_KEY)\n        value = copy.deepcopy(state)\n        value[\"state\"] = \"BLOCKED\"\n        value[\"dispatch_state\"] = \"BLOCKED\"\n        value[\"hard_block\"] = {\n            \"code\": \"REGISTERED_DONE_REQUIRES_TERMINAL_DRIVER_REVIEW\",\n            \"publication_id\": task.get(\"publication_id\"),\n            \"claim_id\": event.get(\"claim_id\"),\n            \"progress_ref\": event.get(\"progress_ref\"),\n            \"server_comment_id\": meta.get(\"comment_id\") if isinstance(meta, dict) else None,\n        }\n        value[\"next_action\"] = (\n            \"Materialize/freeze the Result and obtain terminal Driver review, or append an \"\n            \"authorized correction event; do not redispatch this task.\"\n        )\n        return value\n    return state\n\n\n'''

if text.count(anchor) != 1:
    raise SystemExit(f"expected one overlay anchor, found {text.count(anchor)}")
text = text.replace(anchor, helper + anchor)

old = '''    state = _overlay_result_state(task, state, root, result_state)\n    return _overlay_active_cohort(task, state, root)\n'''
new = '''    state = _overlay_result_state(task, state, root, result_state)\n    state = _overlay_active_cohort(task, state, root)\n    return _block_unreviewed_registered_done(\n        task, state, authenticated, registered_rejected, result_state\n    )\n'''
if text.count(old) != 1:
    raise SystemExit(f"expected one reduce_definition return block, found {text.count(old)}")
text = text.replace(old, new)
path.write_text(text, encoding="utf-8")

Path("tests/test_registered_done_dispatch_guard.py").write_text('''import unittest\n\nfrom tools import research_dispatch as rd\nfrom tools import research_runtime_reducer as rr\n\n\nclass RegisteredDoneDispatchGuardTests(unittest.TestCase):\n    def setUp(self):\n        self.task = {\n            "task_id": "RS-T1",\n            "publication_id": "TP2-TEST",\n            "kind": "RESEARCH",\n            "priority": "P0",\n            "leverage": "HIGH",\n        }\n        self.done = {\n            "schema": rr.EVENT_SCHEMA,\n            "event": "DONE",\n            "task_id": "RS-T1",\n            "claim_id": "c1",\n            "progress_ref": "return.md",\n            rd.GITHUB_META_KEY: {"comment_id": 123, "server_authenticated": True},\n        }\n        self.rejected = [{\n            "index": 0,\n            "reason": "registered DONE requires a frozen result with terminal Driver review",\n        }]\n\n    def fresh_state(self):\n        return {\n            "task_id": "RS-T1",\n            "kind": "RESEARCH",\n            "priority": "P0",\n            "leverage": "HIGH",\n            "state": "HANDOFF_READY",\n            "dispatch_state": "NEEDS_DISPATCH",\n        }\n\n    def test_unreviewed_done_blocks_fresh_redispatch_without_promoting_completion(self):\n        state = rd._block_unreviewed_registered_done(\n            self.task, self.fresh_state(), [self.done], self.rejected, None\n        )\n        self.assertEqual("BLOCKED", state["state"])\n        self.assertEqual("BLOCKED", state["dispatch_state"])\n        self.assertEqual(\n            "REGISTERED_DONE_REQUIRES_TERMINAL_DRIVER_REVIEW",\n            state["hard_block"]["code"],\n        )\n        self.assertEqual(123, state["hard_block"]["server_comment_id"])\n        self.assertIsNone(rr.select_state([state], rr.load_policy(), kind="RESEARCH"))\n\n    def test_existing_result_lifecycle_remains_authoritative(self):\n        original = self.fresh_state()\n        result_state = {"state": "AWAITING_DRIVER_REVIEW"}\n        state = rd._block_unreviewed_registered_done(\n            self.task, original, [self.done], self.rejected, result_state\n        )\n        self.assertEqual(original, state)\n\n    def test_active_lease_is_not_replaced_by_provisional_block(self):\n        original = self.fresh_state()\n        original["state"] = "CLAIMED"\n        original["dispatch_state"] = "LEASED"\n        state = rd._block_unreviewed_registered_done(\n            self.task, original, [self.done], self.rejected, None\n        )\n        self.assertEqual(original, state)\n\n    def test_other_rejection_reason_does_not_trigger_terminal_guard(self):\n        original = self.fresh_state()\n        state = rd._block_unreviewed_registered_done(\n            self.task,\n            original,\n            [self.done],\n            [{"index": 0, "reason": "registered DONE result_id mismatch"}],\n            None,\n        )\n        self.assertEqual(original, state)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")
